    assert merge(base, {"db": {"port": 2}}) == {"db": {"host": "a", "port": 2}, "debug": False}


def test_layers():
    assert load_layers({"a": 1}, {"b": 2}, {"a": 3}) == {"a": 3, "b": 2}


def test_lists_replaced_not_concatenated():
    base = {"items": [1, 2]}
    override = {"items": [3]}
    res = merge(base, override)
    assert res == {"items": [3]}


def test_none_removes_key():
    base = {"a": 1, "b": {"x": 10, "y": 20}}
    override = {"a": None, "b": {"x": None}}
    res = merge(base, override)
    assert res == {"b": {"y": 20}}


def test_dict_and_non_dict_override():
    base = {"a": {"x": 1}}
    override = {"a": 2}
    assert merge(base, override) == {"a": 2}

    base2 = {"a": 2}
    override2 = {"a": {"x": 1}}
    assert merge(base2, override2) == {"a": {"x": 1}}


def test_no_mutation_and_deep_copy():
    base = {"db": {"host": "a", "port": 1}, "list": [1, 2]}
    override = {"db": {"port": 2}}
    res = merge(base, override)

    # Modify result and check inputs are unaffected
    res["db"]["port"] = 99
    res["list"].append(3)

    assert base == {"db": {"host": "a", "port": 1}, "list": [1, 2]}
    assert override == {"db": {"port": 2}}
